mod solution;

fn valid(_input: &str, actual: &str, expected: &str) -> bool { actual == expected }

fn main() {
    let cases = [
        ("text=ababcabcabababd pattern=ababd","10"),
        ("text=aaaa pattern=aa","0"),
        ("text=abcabc pattern=bc","1"),
        ("text=abc pattern=z","-1"),
        ("text=aaaaa pattern=aaa","0"),
        ("  \ntext=ababcabcabababd pattern=ababd\n  ","10"),
        ("\ntext=aaaaa pattern=aaa\n","0")
    ];
    for (i,(input,expected)) in cases.iter().enumerate() {
        let actual = solution::solve(input);
        if !valid(input,&actual,expected) { eprintln!("PRIVATE CASE {} FAILED",i+1); std::process::exit(1); }
    }
    println!("PASS kmp");
}
